{
  "technical_and_design_decisions": [
    "Use ZooKeeper for namespace isolation; store per-tenant metadata under separate namespaces.",
    "Implement interactive authentication using a simple username/password prompt in the admin server, with session tokens.",
    "Use Git branching model with a maintenance branch (e.g., 1.0.x) for minor releases.",
    "For random port discovery, use ZooKeeper to register the admin server's port and have xd-shell read from ZK.",
    "For Kafka consumer upgrade, use the new consumer API and rerun existing test suite.",
    "For streaming ingestion, research Motion-JPEG format and feasibility; no implementation is included in this increment.",
    "Add message rates configuration to servers.yml and parse in cluster view code."
  ],
  "assumptions": [
    "The existing codebase is built on the Spring Framework and follows a modular architecture.",
    "The development team is familiar with ZooKeeper, Kafka, Tomcat, and the existing xd-shell and admin server components.",
    "All user stories are developed sequentially by a single developer.",
    "Each story includes its own unit testing and documentation updates.",
    "The spike for U7 will produce a design document but no production code.",
    "U3 does not involve code changes, only repository and branching management.",
    "U6 involves rerunning existing tests and fixing minor failures; no major architectural changes are required.",
    "No external dependencies beyond those already present in the project."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Implement tenant-specific namespace isolation for ZK metadata",
      "activity_description": "Modify ZooKeeper client code and configuration to allow per-tenant namespace isolation for metadata storage. Includes design, implementation, unit testing, and documentation.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Implement interactive login to Admin server",
      "activity_description": "Add interactive username/password authentication for the Admin server. Includes prompting, session handling, and security considerations. Includes implementation, testing, and documentation.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Create maintenance branch for minor releases",
      "activity_description": "Create a maintenance branch (e.g., 1.0.x) in the version control system and update the branching strategy. No code changes. Includes coordination with CI/CD.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Clean up deprecated functions in module registry, Shell, Admin-UI",
      "activity_description": "Remove deprecated functions (e.g., download of module definitions) and clean up related code in Shell and Admin-UI modules. Includes testing to ensure no regressions.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Enable xd-shell to access Admin server on random port",
      "activity_description": "Implement discovery of the Admin server's random Tomcat port via ZooKeeper and enable xd-shell to connect. Includes spike results and implementation. Covers research, coding, testing, and documentation.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Rerun failing tests after Kafka consumer upgrade",
      "activity_description": "Upgrade to the new Kafka consumer API and rerun the existing test suite. Fix any test failures. Includes test configuration updates and verification.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Research and design for Motion-JPEG streaming ingest",
      "activity_description": "Research feasibility of implementing Motion-JPEG format for streaming audio/video data ingest. Produce design specifications. No implementation code delivered in this increment.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Add config parameter to servers.yml for message rates",
      "activity_description": "Add a configuration parameter to servers.yml to enable/disable message rates in the cluster view. Implement code to read and apply the setting. Includes testing and documentation.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "System integration testing and release preparation",
      "activity_description": "Perform end-to-end integration testing across all changes, fix integration issues, and prepare the release artifacts and deployment instructions.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 26.5
  }
}

